def _append_basis(
    circuit: QuantumCircuit,
    block: DFDeterministicBlockSpec,
    *,
    inverse: bool,
) -> None:
    operations = list(block.runtime_basis_operations)
    if inverse:
        operations.reverse()
    for gate, qubits in operations:
        circuit.append(gate.inverse() if inverse else gate, list(qubits))
